mapper.sql:
WITH RECURSIVE st AS (
  SELECT s.id AS root_id, s.id AS node_id, 1 AS d
    FROM case_set s
   WHERE s.workspace_id = #{workspaceId} AND s.req_id = #{reqId}
  UNION ALL
  SELECT st.root_id, c.id, st.d + 1
    FROM case_set c JOIN st ON c.parent_id = st.node_id
   WHERE st.d < 64
     AND c.workspace_id = #{workspaceId} AND c.req_id = #{reqId}
)

mapper.select:
SELECT * FROM case_set
WHERE workspace_id = #{workspaceId} AND req_id = #{reqId}
ORDER BY COALESCE(sort_order, 0), created_at, id

mapper.delete:
DELETE m FROM case_set_member m
JOIN case_set s ON s.id = m.set_id
WHERE s.workspace_id = #{workspaceId} AND s.req_id = #{reqId}

DELETE m FROM case_set_member m
JOIN case_set s ON s.id = m.set_id
WHERE s.workspace_id = #{workspaceId}

